-- Real Dhaka service geography, transcribed from
-- service_area_details_inhouse_sheba_md.md. Idempotent: every statement
-- upserts by name, so re-running this after an edit to the source updates
-- zone/sort assignments rather than duplicating rows.

-- The pre-existing area used a shorter name for the same real place.
UPDATE areas SET name = 'Bashundhara Residential Area (R/A)' WHERE name = 'Bashundhara R/A' AND NOT EXISTS (SELECT 1 FROM areas WHERE name = 'Bashundhara Residential Area (R/A)');

